//! Solidity ABI of the contracts we call, generated by `alloy_sol_types::sol!` (no hand-packed bytes).
//!
//! `ExactInputSingleParams` has SIX fields on the deployed routers (`minHopPriceX36` sits between
//! `amountOutMinimum` and `hookData`, matching Uniswap v4-periphery `main`). The older five-field layout does not
//! decode real router transactions on this chain; the golden test in `uniswap.rs` pins the six-field layout to a
//! real transaction byte for byte.
#![allow(clippy::too_many_arguments)]
alloy_sol_types::sol! {
    struct PoolKey {
        address currency0;
        address currency1;
        uint24 fee;
        int24 tickSpacing;
        address hooks;
    }

    struct ExactInputSingleParams {
        PoolKey poolKey;
        bool zeroForOne;
        uint128 amountIn;
        uint128 amountOutMinimum;
        uint256 minHopPriceX36;
        bytes hookData;
    }

    struct QuoteExactSingleParams {
        PoolKey poolKey;
        bool zeroForOne;
        uint128 exactAmount;
        bytes hookData;
    }

    interface IUniversalRouter {
        function execute(bytes commands, bytes[] inputs, uint256 deadline) external payable;
    }

    interface IPermit2 {
        function approve(address token, address spender, uint160 amount, uint48 expiration) external;
        function allowance(address user, address token, address spender) external view returns (uint160 amount, uint48 expiration, uint48 nonce);
    }

    interface IERC20 {
        function approve(address spender, uint256 amount) external returns (bool);
        function allowance(address owner, address spender) external view returns (uint256);
    }

    interface IV4Quoter {
        function quoteExactInputSingle(QuoteExactSingleParams params) external returns (uint256 amountOut, uint256 gasEstimate);
    }

    interface IStateView {
        function getSlot0(bytes32 poolId) external view returns (uint160 sqrtPriceX96, int24 tick, uint24 protocolFee, uint24 lpFee);
        function getLiquidity(bytes32 poolId) external view returns (uint128 liquidity);
    }
}

/// Universal Router command byte: run a v4 action plan.
pub const CMD_V4_SWAP: u8 = 0x10;

/// v4-periphery `Actions` constants (verified against `src/libraries/Actions.sol`).
pub const ACT_SWAP_EXACT_IN_SINGLE: u8 = 0x06;
pub const ACT_SETTLE: u8 = 0x0b;
pub const ACT_SETTLE_ALL: u8 = 0x0c;
pub const ACT_TAKE_ALL: u8 = 0x0f;

/// `ActionConstants.OPEN_DELTA`: an `amountIn` of 0 means "use the whole open credit of the input currency".
pub const OPEN_DELTA: u128 = 0;

/// keccak256("Transfer(address,address,uint256)")
pub const TOPIC_TRANSFER: &str = "0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef";
/// keccak256("Swap(bytes32,address,int128,int128,uint160,uint128,int24,uint24)") (PoolManager)
pub const TOPIC_SWAP: &str = "0x40e9cecb9f5f1f1c5b9c97dec2917b7ee92e57ba5563708daca94dd84ad7112f";

/// Human-readable names for revert selectors we expect to see (logs only).
pub fn revert_name(data: &str) -> &'static str {
    let d = data.trim_start_matches("0x");
    let has = |s: &str| d.contains(s);
    if has("8b063d73") {
        "V4TooLittleReceived (slippage limit hit)"
    } else if has("4713c18b") {
        "V4TooLittleReceivedPerHopSingle"
    } else if has("7a5ed734") {
        "NotEnoughLiquidity (pool drained)"
    } else if has("486aa307") {
        "PoolNotInitialized"
    } else if has("5212cba1") {
        "CurrencyNotSettled (token transfer amount mismatch)"
    } else if has("5bf6f916") || has("bfb22adf") {
        "deadline passed"
    } else if has("f96fb071") || has("d81b2f2e") {
        "Permit2 allowance missing or expired"
    } else if has("675cae38") {
        "InsufficientToken"
    } else {
        "unknown revert"
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloy_primitives::keccak256;
    use alloy_sol_types::SolCall;

    #[test]
    fn selectors_match_known_values() {
        assert_eq!(IUniversalRouter::executeCall::SELECTOR, [0x35, 0x93, 0x56, 0x4c]);
        assert_eq!(IPermit2::approveCall::SELECTOR, [0x87, 0x51, 0x7c, 0x45]);
        assert_eq!(IERC20::approveCall::SELECTOR, [0x09, 0x5e, 0xa7, 0xb3]);
        assert_eq!(IV4Quoter::quoteExactInputSingleCall::SELECTOR, [0xaa, 0x9d, 0x21, 0xcb]);
        assert_eq!(IStateView::getSlot0Call::SELECTOR, [0xc8, 0x15, 0x64, 0x1c]);
        assert_eq!(IStateView::getLiquidityCall::SELECTOR, [0xfa, 0x67, 0x93, 0xd5]);
    }

    #[test]
    fn event_topics_match_signatures() {
        assert_eq!(format!("{:#x}", keccak256("Transfer(address,address,uint256)")), TOPIC_TRANSFER);
        assert_eq!(format!("{:#x}", keccak256("Swap(bytes32,address,int128,int128,uint160,uint128,int24,uint24)")), TOPIC_SWAP);
    }
}
